// src/screens/GalleryScreen.js - экран галереи изображений
import React, { useState, useEffect } from 'react';
import { 
  View, 
  Text, 
  StyleSheet, 
  ScrollView,
  Image,
  TouchableOpacity,
  Alert,
  Modal 
} from 'react-native';
import * as ImagePicker from 'expo-image-picker';
import * as Audio from 'expo-av'; // 💡 ДОБАВЛЕНО для звука
import useStorage from '../hooks/useStorage'; // ✅ ДОБАВЛЕНО

const GALLERY_STORAGE_KEY = 'gallery_images'; // Ключ для хранения URI изображений
const PHOTO_COUNT_KEY = 'photo_count';       // Ключ для счетчика фотографий

// URL для звукового оповещения при добавлении фото
const ADD_SOUND_URI = 'https://www.soundjay.com/button/beep-07a.wav';

const GalleryScreen = () => {
  // ✅ Использование useStorage для хранения списка изображений
  const { 
    value: images, 
    setValue: setImages, 
    loading: imagesLoading, 
    clearData: clearImages 
  } = useStorage(GALLERY_STORAGE_KEY, []);

  // ✅ Использование useStorage для счетчика фотографий
  const { 
    value: photoCount, 
    setValue: setPhotoCount, 
    clearData: clearPhotoCount 
  } = useStorage(PHOTO_COUNT_KEY, 0);

  const [selectedImage, setSelectedImage] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);

  // 💡 Функция для воспроизведения звука
  const playSoundEffect = async (uri) => {
    try {
      const { sound } = await Audio.Sound.createAsync({ uri });
      await sound.playAsync();
      // Выгружаем звук, чтобы освободить память после воспроизведения
      sound.setOnPlaybackStatusUpdate((status) => {
        if (status.didJustFinish) {
          sound.unloadAsync();
        }
      });
    } catch (error) {
      console.error('Ошибка воспроизведения звука:', error);
    }
  };

  // Добавление изображения
  const addImage = async (useCamera = false) => {
    let permissionResult;
    let pickerResult;

    try {
      if (useCamera) {
        permissionResult = await ImagePicker.requestCameraPermissionsAsync();
        if (!permissionResult.granted) {
          Alert.alert('Разрешение необходимо', 'Для использования камеры необходимо разрешение.');
          return;
        }
        pickerResult = await ImagePicker.launchCameraAsync({
          mediaTypes: ImagePicker.MediaTypeOptions.Images,
          allowsEditing: true,
          aspect: [4, 3],
          quality: 0.8,
        });
      } else {
        permissionResult = await ImagePicker.requestMediaLibraryPermissionsAsync();
        if (!permissionResult.granted) {
          Alert.alert('Разрешение необходимо', 'Для доступа к галерее необходимо разрешение.');
          return;
        }
        pickerResult = await ImagePicker.launchImageLibraryAsync({
          mediaTypes: ImagePicker.MediaTypeOptions.Images,
          allowsMultipleSelection: true,
          aspect: [4, 3],
          quality: 0.8,
        });
      }

      if (!pickerResult.canceled) {
        const assets = pickerResult.assets || [pickerResult]; // Унификация результата

        const newImages = assets.map(asset => ({
          id: Date.now() + Math.random(),
          uri: asset.uri,
          timestamp: new Date().toLocaleString()
        }));

        // Обновление списка изображений в хранилище
        setImages(prev => [...prev, ...newImages]);

        // 🚀 Обновление счетчика!
        setPhotoCount(prevCount => prevCount + newImages.length);

        // 💡 Воспроизведение звука
        playSoundEffect(ADD_SOUND_URI);

      }
    } catch (error) {
      Alert.alert('Ошибка', `Не удалось добавить изображения: ${error.message}`);
    }
  };

  // Удаление изображения
  const deleteImage = (id) => {
    setImages(prev => prev.filter(img => img.id !== id));
    // 🚀 Обновление счетчика при удалении
    setPhotoCount(prevCount => Math.max(0, prevCount - 1)); 
    setModalVisible(false);
  };

  // ... (Остальной код viewImage, closeModal)

  return (
    <ScrollView style={styles.container}>
      <Text style={styles.headerText}>
        📸 Total Photos Added: {photoCount} 
      </Text>

      {/* ... (Кнопки) */}

      {/* ... (Отображение галереи) */}
    </ScrollView>
  );
};
// ... (Стили)
export default GalleryScreen;
